svg.metadata:
{"project": "EvidenceGraph", "diagram": "02_langgraph_agent_architecture", "title": "EvidenceGraph — LangGraph Agent Workflow", "description": "Execution flow from user request through Zod validation, planning agent, optional human approval and checkpoint, research agent using web, hybrid RAG and graph tools, evidence evaluation with bounded research loop, verification agent, report agent, output guardrails, and final cited report. PostgreSQL provides resumable checkpoints.", "source_format": "graphviz_dot", "graphviz_dot": "digraph EvidenceGraphAgents {
 graph [label="EVIDENCEGRAPH / LANGGRAPH AGENT WORKFLOW", labelloc=t, labeljust=l,
 fontsize=25, fontname="DejaVu Sans", fontcolor="#142338", bgcolor="#FFFFFF",
 rankdir=TB, pad=0.37, nodesep=0.60, ranksep=0.62,
 splines=polyline, compound=true, newrank=true, outputorder=edgesfirst];
 node [shape=box, style="rounded,filled", fontname="DejaVu Sans", fontsize=13,
 color="#CBD5E1", fillcolor="#FFFFFF", fontcolor="#172E44", penwidth=1.4,
 margin="0.22,0.14"];
 edge [color="#7D91A9", penwidth=1.6, arrowsize=0.78, fontsize=10.5,
 fontname="DejaVu Sans", fontcolor="#64748B"];

 start [label="RESEARCH REQUEST", shape=ellipse, fillcolor="#EFF6FF", color="#8CB4EA"];
 validate [label="Validation + input guardrails\nZod · authorization · scope checks", fillcolor="#F1F5F9"];
 plan [label="PLANNING AGENT\nDecompose question into subquestions\nCreate investigation plan", fillcolor="#DDEBFD", color="#7DAADB"];
 approval [label="Approval needed?", shape=diamond, fillcolor="#FEF0D5", color="#D9B46E", margin="0.22,0.08"];
 wait [label="HUMAN-IN-THE-LOOP\nPause execution · Save checkpoint\nWait for review / feedback", fillcolor="#F2E9FC", color="#B49AD5"];
 research [label="RESEARCH AGENT\nSelect tools · Execute subquestions\nCollect evidence and metadata", fillcolor="#DDEBFD", color="#7DAADB"];

 subgraph cluster_tools {
 label="RESEARCH TOOLS"; labelloc=t; labeljust=l; fontsize=14;
 style="rounded,filled"; color="#D1E8DC"; fillcolor="#F3FBF6"; margin=17;
 search [label="Web search / crawling", fillcolor="#DCF0E5", color="#80B89D"];
 rag [label="Hybrid RAG retrieval", fillcolor="#DCF0E5", color="#80B89D"];
 graph_tool [label="Graph retrieval", fillcolor="#DCF0E5", color="#80B89D"];
 {rank=same; search; rag; graph_tool}
 }

 evaluate [label="EVIDENCE EVALUATOR\nCoverage · Relevance · Source quality", fillcolor="#DCF0E5", color="#80B89D"];
 sufficient [label="Enough evidence?\nOr budget exhausted?", shape=diamond, fillcolor="#FEF0D5", color="#D9B46E", margin="0.25,0.12"];
 verify [label="VERIFICATION AGENT\nCross-check claims and citations\nIdentify contradictions / uncertainty", fillcolor="#DDEBFD", color="#7DAADB"];
 report [label="REPORT AGENT\nEvidence-grounded synthesis\nStructured sections + citation mapping", fillcolor="#DDEBFD", color="#7DAADB"];
 guard [label="OUTPUT GUARDRAILS\nValidate schema + cited spans\nReject unsupported claims", fillcolor="#F1F5F9"];
 end [label="RESEARCH REPORT\nCitations · Graph · Execution trace", fillcolor="#E2F5E8", color="#78BC94", penwidth=2];
 checkpoint [label="PostgreSQL checkpointer\nResumable LangGraph state", shape=cylinder,
 fillcolor="#FFF0D1", color="#D9B469"];

 start -> validate -> plan -> approval;
 approval -> wait [label="YES"];
 approval -> research [label="NO"];
 wait -> research [label="resume"];
 research -> search;
 research -> rag;
 research -> graph_tool;
 search -> evaluate;
 rag -> evaluate;
 graph_tool -> evaluate;
 evaluate -> sufficient;
 sufficient -> verify [label="YES / LIMIT REACHED"];
 sufficient -> research [label="NO · WITHIN BUDGET", color="#BE8D45", fontcolor="#A87937", constraint=false, penwidth=2.0];
 verify -> report -> guard -> end;

 plan -> checkpoint [style=dashed, color="#C7A25B", constraint=false];
 wait -> checkpoint [style=dashed, color="#C7A25B", constraint=false];
 research -> checkpoint [style=dashed, color="#C7A25B", constraint=false];
 verify -> checkpoint [style=dashed, color="#C7A25B", constraint=false];
 {rank=same; wait; research}
 {rank=same; verify; checkpoint}
}
"}
